WITH exploded AS (SELECT id, host, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW EXPLODE(context) li AS k, value) SELECT id, host, latency_ms, status_code, k, value, DENSE_RANK() OVER (PARTITION BY k ORDER BY status_code) AS status_code_dense_rank, RANK() OVER (PARTITION BY k, host ORDER BY latency_ms) AS latency_ms_rank, FIRST_VALUE(latency_ms, TRUE) OVER (PARTITION BY k ORDER BY status_code, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_latency_ms FROM exploded;
